    const ctx = this.ctx, W = this.canvas.width, H = this.canvas.height;
    // Premium dark obsidian glass panel
    ctx.fillStyle = "#0a0d14";
    ctx.fillRect(0, 0, W, H);

    // Subtle LED dot-matrix grid pattern
    ctx.fillStyle = "rgba(255, 255, 255, 0.035)";
    for (let x = 12; x < W; x += 8) {
      for (let y = 12; y < H; y += 8) {
        ctx.fillRect(x, y, 2, 2);
      }
    }

    // Outer cybernetic border
    ctx.strokeStyle = "#1e293b";
    ctx.lineWidth = 6;
    ctx.strokeRect(14, 14, W - 28, H - 28);

    // Neon accent edge
    ctx.strokeStyle = "rgba(56, 189, 248, 0.4)";
    ctx.lineWidth = 1.5;
    ctx.strokeRect(20, 20, W - 40, H - 40);

    // Top Header Banner
    const headGrad = ctx.createLinearGradient(W * 0.2, 0, W * 0.8, 0);
    headGrad.addColorStop(0, "rgba(6, 182, 212, 0.2)");
    headGrad.addColorStop(0.5, "rgba(245, 158, 11, 0.35)");
    headGrad.addColorStop(1, "rgba(244, 63, 94, 0.2)");
    ctx.fillStyle = headGrad;
    ctx.fillRect(28, 28, W - 56, 56);

    ctx.strokeStyle = "rgba(245, 158, 11, 0.6)";
    ctx.lineWidth = 1;
    ctx.strokeRect(28, 28, W - 56, 56);

    // Arena Title
    ctx.font = "bold 26px -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif";
    ctx.textAlign = "center";
    ctx.fillStyle = "#f59e0b";
    ctx.shadowColor = "rgba(245, 158, 11, 0.8)";
